    // In case if hashes match let's make sure that substrings are equal.
    // In case of hash collision the strings may not be equal.
    if (
      wordHash === currentFrameHash
      && text.substring(charIndex, charIndex + word.length) === word
    ) {
      return charIndex;
    }
  }

  return -1;
}

